CREATE TABLE users(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'admin',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE categories(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT UNIQUE NOT NULL);
CREATE TABLE products(id INTEGER PRIMARY KEY AUTOINCREMENT,category_id INTEGER NOT NULL,name TEXT NOT NULL,description TEXT,price INTEGER NOT NULL,stock INTEGER NOT NULL DEFAULT 0,image TEXT,is_active INTEGER NOT NULL DEFAULT 1,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE customers(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,phone TEXT,email TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE orders(id INTEGER PRIMARY KEY AUTOINCREMENT,invoice TEXT UNIQUE NOT NULL,customer_id INTEGER,order_date TEXT NOT NULL,subtotal INTEGER NOT NULL,discount INTEGER NOT NULL DEFAULT 0,total INTEGER NOT NULL,payment_method TEXT NOT NULL,payment_status TEXT NOT NULL DEFAULT 'PAID',order_status TEXT NOT NULL DEFAULT 'COMPLETED',cash_received INTEGER DEFAULT 0,change_amount INTEGER DEFAULT 0,coupon_code TEXT,payment_reference TEXT);
CREATE TABLE order_items(id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL,product_id INTEGER NOT NULL,product_name TEXT NOT NULL,price INTEGER NOT NULL,qty INTEGER NOT NULL,subtotal INTEGER NOT NULL);
CREATE TABLE financial_entries(id INTEGER PRIMARY KEY AUTOINCREMENT,entry_date TEXT NOT NULL,type TEXT NOT NULL,category TEXT NOT NULL,description TEXT NOT NULL,amount INTEGER NOT NULL,order_id INTEGER,reference TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE coupons(id INTEGER PRIMARY KEY AUTOINCREMENT,code TEXT UNIQUE NOT NULL,discount_percent INTEGER DEFAULT 0,discount_amount INTEGER DEFAULT 0,min_purchase INTEGER DEFAULT 0,active INTEGER DEFAULT 1);
